ALTER TABLE bracel_jobs ADD COLUMN IF NOT EXISTS queue text NOT NULL DEFAULT 'default', ADD COLUMN IF NOT EXISTS priority integer NOT NULL DEFAULT 0, ADD COLUMN IF NOT EXISTS dispatch_delay_seconds bigint NOT NULL DEFAULT 0; CREATE INDEX IF NOT EXISTS bracel_jobs_queue_due ON bracel_jobs(queue,status,available_at); CREATE TABLE IF NOT EXISTS bracel_calendar(name text PRIMARY KEY,expression text NOT NULL,timezone text NOT NULL,kind text NOT NULL,version integer NOT NULL,payload jsonb NOT NULL,max_attempts integer NOT NULL,next_due_at timestamptz NOT NULL,last_job uuid,enabled boolean NOT NULL DEFAULT true);